"""Build a code-only local updater, with no saved workforce or financial data."""
from pathlib import Path
import zipfile
r=Path(__file__).resolve().parent.parent
payloads={'diagnostics':'efficiency-diagnostics.js','picker':'efficiency-picker.js','engine':'efficiency.js'}
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Efficiency tab updater</title><style>body{font:16px/1.6 system-ui,sans-serif;background:#f3f5f3;color:#17211c;margin:0;padding:24px}main{max-width:760px;margin:auto;background:white;border:1px solid #d8dfd9;border-radius:10px;padding:28px}h1{font-size:25px;margin-top:0}label{font-weight:650;display:block}input{font:inherit;max-width:100%}#status{background:#f3f5f3;padding:14px}a{display:inline-block;background:#17211c;color:white;padding:12px 16px;border-radius:7px;text-decoration:none}a[hidden]{display:none}.note{font-size:14px;color:#55615a}@media(max-width:600px){body{padding:12px}main{padding:18px}}</style></head><body><main><h1>Read output from the Efficiency tab</h1><p>Connect the Efficiency worksheet's production dates and packs to Daily Labour / UPLH.</p><ol><li>Save your current cockpit.</li><li>Select that latest saved HTML below.</li><li>Download and open the updated cockpit.</li><li>In Daily Labour, select the Production Date and upload your current Efficiency workbook again.</li></ol><label for="source">Choose your saved cockpit HTML</label><input id="source" type="file" accept=".html,.htm"><p id="status" role="status" aria-live="polite">No file selected.</p><a id="download" hidden>Download updated cockpit</a><p class="note">The new preview shows the worksheet, source dates and output field. Old records remain available for audit.</p><p class="note">Everything runs on your PC. Nothing is uploaded. Saved records, previous amendments and the original file are retained.</p></main>'''
parts=[head]
for id,filename in payloads.items():
 code=(r/'scripts/daily-labour'/filename).read_text();assert '</script' not in code.lower();parts.append('<script id="'+id+'" type="text/plain">'+code+'</script>')
patch=(r/'scripts/daily-labour/efficiency-date-patch.js').read_text();assert '</script' not in patch.lower();parts.append('<script>'+patch+'</script>')
parts.append('''<script>(function(){'use strict';const input=document.getElementById('source'),status=document.getElementById('status'),download=document.getElementById('download');let url,request=0;
input.onchange=async()=>{const current=++request;download.hidden=true;try{const file=input.files[0];if(!file)return;status.textContent='Checking your saved cockpit…';const source=await file.text();if(current!==request)return;const code=id=>document.getElementById(id).textContent,result=patchEfficiencyDates(source,code('diagnostics'),code('picker'),code('engine'));
if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(new Blob([result],{type:'text/html'}));download.href=url;download.download=file.name.replace(/\\.html?$/i,'')+'_Efficiency_Tab.html';download.hidden=false;status.textContent='Ready. Open the updated cockpit, then upload Efficiency.xlsm again so it reads the Efficiency tab.';
}catch(error){if(current===request)status.textContent=error.message;}};})();</script></body></html>''')
(r/'Cockpit_Efficiency_Tab_Updater.html').write_text(''.join(parts))
with zipfile.ZipFile(r/'Cockpit_Efficiency_Tab_Updater.zip','w',zipfile.ZIP_DEFLATED) as z:
 for name in ['Cockpit_Efficiency_Tab_Updater.html','Cockpit_Efficiency_Tab_Guide.md']:z.write(r/name,name)
print('Built code-only Efficiency tab updater and ZIP')
